import{_ as t,o,c as a,a3 as i}from"./chunks/framework.DAK02U1-.js";const u=JSON.parse('{"title":"Source Code Overview","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Source Code Overview | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/design/overview"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/design/overview"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/design/overview"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/design/overview"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/design/overview"}]]},"headers":[],"relativePath":"clice/design/overview.md","filePath":"en/clice/design/overview.md","lastUpdated":1794005519000}'),n={name:"clice/design/overview.md"};function s(r,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="source-code-overview" tabindex="-1">Source Code Overview <a class="header-anchor" href="#source-code-overview" aria-label="Permalink to &quot;Source Code Overview&quot;">​</a></h1><p>This document describes the responsibilities and role of each module in the clice source tree, providing readers with a high-level understanding of the overall project structure. For detailed design information on each module, refer to the corresponding topic documents.</p><h2 id="project-vision" tabindex="-1">Project Vision <a class="header-anchor" href="#project-vision" aria-label="Permalink to &quot;Project Vision&quot;">​</a></h2><p>clice is a brand-new C++ language server, redesigned from the architecture level to solve long-standing problems in previous C++ language servers. Key features:</p><ul><li><p><strong>Compilation Context</strong>: clice is the first language server to introduce compilation context as a formal concept. Every step of compilation, indexing, and querying explicitly distinguishes the current compilation context, and users can query and switch between them. See <a href="./compilation-context">Compilation Context</a>.</p></li><li><p><strong>Multi-process Architecture</strong>: A master + worker process model isolates Clang&#39;s memory leaks and crashes while enabling priority-aware scheduling and real-time memory monitoring. See <a href="./multi-process">Multi-process Architecture</a>.</p></li><li><p><strong>Coroutine-based Async Model</strong>: Built on C++20 coroutines and the kotatsu library, replacing traditional callback-style async and making business logic clearer.</p></li><li><p><strong>Unified Compile Scheduling</strong>: Every expensive build product — preamble PCHs, C++20 module PCMs, document ASTs, one unit&#39;s compile for its index or its lint — is a node in a single compile task graph with shared builds, real-time cooperative cancellation, and dependency-aware invalidation. See <a href="./task-graph">Compile Task Graph</a>.</p></li></ul><h2 id="module-overview" tabindex="-1">Module Overview <a class="header-anchor" href="#module-overview" aria-label="Permalink to &quot;Module Overview&quot;">​</a></h2><h3 id="src-support-—-foundation-utility-library" tabindex="-1"><code>src/support/</code> — Foundation Utility Library <a class="header-anchor" href="#src-support-—-foundation-utility-library" aria-label="Permalink to &quot;`src/support/` — Foundation Utility Library&quot;">​</a></h3><p>General-purpose utilities and infrastructure shared by all other modules.</p><ul><li><code>FuzzyMatcher</code>: Token-aware fuzzy matching for code completion and symbol search</li><li>Markup: The markdown or plain text a card or a query answer is rendered in</li><li><code>FailureRecord</code>: What is remembered of an operation that failed — how many times in a row, when and why — and its operation&#39;s policy for when it runs again: how many failures stop it, a cooldown, whether a change of its inputs or a save retries it</li><li>Logging, filesystem abstractions, string utilities, etc.</li></ul><h3 id="src-vfs-—-file-identity-and-versions" tabindex="-1"><code>src/vfs/</code> — File Identity and Versions <a class="header-anchor" href="#src-vfs-—-file-identity-and-versions" aria-label="Permalink to &quot;`src/vfs/` — File Identity and Versions&quot;">​</a></h3><ul><li><code>FileTable</code>: Internalizes file paths as stable <code>Fid</code> identifiers used throughout the system, and owns the shared per-file facts derived from them — the last observation of each file on disk, content versions, directory listings. A file has one <code>Fid</code> however a path spells it: it is identified by the name the operating system gives it (through symlinks, and on Windows through letter case, junctions and subst drives), and shown to the user under the name the user knows it by — the open document&#39;s, else its own path under the workspace folder the user opened, never the spelling an include lookup reached it by. The two-layer freshness check (stat fast path, then content hash) lives here once and is shared by every consumer: PCH validation, index staleness, and disk polling. Every look that finds other content than the last one is reported as a change, whoever looked.</li><li><code>CacheStore</code>: The on-disk artifact store for file-shaped build products (PCH/PCM and friends) — atomic pair commits, namespace quotas, LRU eviction, and crash recovery</li></ul><h3 id="src-settings-—-settings" tabindex="-1"><code>src/settings/</code> — Settings <a class="header-anchor" href="#src-settings-—-settings" aria-label="Permalink to &quot;`src/settings/` — Settings&quot;">​</a></h3><ul><li><code>Settings</code>: Loading and merging of <code>clice.toml</code> and LSP <code>initializationOptions</code>, located errors and unknown-key warnings, the JSON schema the configuration docs are generated from, and choosing the build configuration.</li><li><code>Rules</code>: The rules of <code>clice.toml</code> under one configuration, the one place that knows rule priority: which rules a file matches, how they edit its command, whether it is indexed, linted and formatted, which default command covers it, and which databases it compiles from in what order.</li></ul><h3 id="src-command-—-compilation-command-processing" tabindex="-1"><code>src/command/</code> — Compilation Command Processing <a class="header-anchor" href="#src-command-—-compilation-command-processing" aria-label="Permalink to &quot;`src/command/` — Compilation Command Processing&quot;">​</a></h3><p>Commands read from the compilation database (CDB) are raw commands generated by the build system and cannot be fed directly to the Clang frontend -- they may contain options meant only for code generation, lack system header search paths, or include parameters irrelevant to a language server. This module parses each command once into a structured form that the rest of the system consumes.</p><ul><li><code>CommandTable</code>: Every command clice knows, parsed once into an interned, classified argument structure identified by a stable <code>CommandID</code>, with what derives from one command: its input language, the precompiled headers it writes and reads, its command hash, its driver-level renders</li><li><code>CompilationDatabase</code>: Loads, reloads and diffs the <code>compile_commands.json</code> files, their entries normalized (<code>Normalizer</code>) into the <code>CommandTable</code>; the rules&#39; edits apply on top of an entry&#39;s command (<code>apply_edits</code>)</li><li><code>Toolchain</code>: Queries system compilers for implicit compilation parameters (such as system header search paths), with a two-layer cache — query results per driver invocation shape, and synthesized flag sets per input kind — and renders the <code>-cc1</code> command lines; how each compiler kind is asked (GCC-style, cl, nvcc, clang&#39;s own driver) lives under <code>src/command/toolchains/</code></li><li><code>SearchConfig</code>: A four-tier model for header search paths (Quoted / Angled / System / After), matching Clang&#39;s internal search logic</li></ul><p>See <a href="./command-resolve">Compilation Command Resolution</a>.</p><h3 id="src-compile-—-compilation-abstraction" tabindex="-1"><code>src/compile/</code> — Compilation Abstraction <a class="header-anchor" href="#src-compile-—-compilation-abstraction" aria-label="Permalink to &quot;`src/compile/` — Compilation Abstraction&quot;">​</a></h3><p>Wraps the Clang compiler, abstracting Clang APIs into safe, unified compilation interfaces. This layer is purely a compilation abstraction with no server logic.</p><ul><li><code>CompilationUnit</code>: one compilation&#39;s AST, what Clang reported while it ran (diagnostics, preprocessor directives, tokens, dependencies), and the helpers that read them, such as source location mappings. <code>compile()</code> returns it, and it is the primary input for <code>src/feature/</code> and <code>src/index/</code>.</li><li><code>CompilationParams</code>: Describes a single compilation: its kind (Preprocess / Preamble / ModuleInterface / Content / Whole / Completion), its input (the command, the files served from memory, the PCH and PCMs it loads), and what else runs over the parse, such as clang-tidy.</li><li>Diagnostic and clang-tidy collection during compilation.</li><li>What the layers above derive from the AST, such as the semantic map, is built on first use and kept with the unit (<code>CompilationUnit::get</code>).</li></ul><h3 id="src-syntax-—-lightweight-syntax-processing" tabindex="-1"><code>src/syntax/</code> — Lightweight Syntax Processing <a class="header-anchor" href="#src-syntax-—-lightweight-syntax-processing" aria-label="Permalink to &quot;`src/syntax/` — Lightweight Syntax Processing&quot;">​</a></h3><p>Syntax-level processing that does not require a full AST. Runs before compilation to quickly obtain structural information and dependency relationships for files.</p><ul><li><code>Lexer</code> and the lexical scan: <code>Lexer</code> is a token-level utility built on Clang&#39;s raw lexer that marks directive lines, their keywords and header names. The lexical scan lexes a file once into its tokens, comments and directive lines (with the conditional blocks around each), its include guard and its module declarations; the features answered from an open file&#39;s compiled unit share the one scan the unit caches. Neither runs the preprocessor.</li><li><code>DependencyGraph</code>: A global include/module dependency graph supporting forward queries, reverse queries, host source file search, include chain lookup, etc.</li><li>Dependency scanning: Wraps Clang&#39;s <code>DependencyDirectivesScanner</code> to quickly extract include and module dependencies</li><li><code>IncludeResolver</code>: Resolves include paths to actual files based on search path configuration</li><li>Header contexts: Builds the prefix/suffix files that let a header compile under its host&#39;s preprocessor state</li><li>Documentation comments: Finds the comment documenting a declaration in a file&#39;s text, the same way for a compiled unit and for the index, and reads it as Doxygen and Markdown — commands, parameters, return values, <code>@copydoc</code> — into one structured form that hover and <code>clice query</code> render</li></ul><p>See <a href="./dependency-scanning">Dependency Scanning</a>.</p><h3 id="src-semantic-—-semantic-analysis" tabindex="-1"><code>src/semantic/</code> — Semantic Analysis <a class="header-anchor" href="#src-semantic-—-semantic-analysis" aria-label="Permalink to &quot;`src/semantic/` — Semantic Analysis&quot;">​</a></h3><p>Semantic analysis capabilities beyond Clang&#39;s native APIs, over the AST of a compilation unit.</p><ul><li><code>Semantics</code>: The unified semantic map — a single AST traversal per compilation records every interesting node and its token ownership; selection, features, and index production are pure queries over the map rather than separate AST walks</li><li><code>EntityTable</code>: The identity of a declaration, equal across translation units for the declarations the compiler would merge</li><li><code>TemplateResolver</code>: Resolves dependent names through pseudo-instantiation, enabling semantic analysis to see through template contexts. See <a href="./template-resolver">Template Resolver</a>.</li><li><code>SymbolKind</code> / <code>RelationKind</code>: Fine-grained symbol kinds and relation types</li></ul><h3 id="src-index-—-symbol-index" tabindex="-1"><code>src/index/</code> — Symbol Index <a class="header-anchor" href="#src-index-—-symbol-index" aria-label="Permalink to &quot;`src/index/` — Symbol Index&quot;">​</a></h3><p>Symbol indexing system with cross-translation-unit query support. Layered as:</p><ul><li><code>TUIndex</code>: Index entries produced from a single compilation, projected from the semantic map</li><li><code>ProjectIndex</code>: The global layer — externally visible symbols, plus the record of which translation units contributed which files — in memory and on disk in one type: it merges translation units&#39; indexes, judges their freshness, saves its changes to the index database and loads them back</li><li><code>Shard</code>: The per-file storage unit. Each compilation context that preprocesses the file differently contributes a variant, deduplicated by the content identity of its encoded entries; names local to the file live in the shard itself, only external names enter the <code>ProjectIndex</code></li><li><code>BlobDatabase</code>: Persistence backend — all index blobs live in a single LMDB database</li><li><code>IndexQuery</code>: Read-only queries over every index source — the project index, per-file shards, and the open documents&#39; indexes its owner hands it as plain data for one read — under one freshness arbitration, answering in domain values that the transports project onto their protocols; a query may also ask the other projects&#39; views about the same entity, each answering for the files it serves</li></ul><p>See <a href="./symbol-index">Symbol Index</a>.</p><h3 id="src-feature-—-lsp-feature-implementations" tabindex="-1"><code>src/feature/</code> — LSP Feature Implementations <a class="header-anchor" href="#src-feature-—-lsp-feature-implementations" aria-label="Permalink to &quot;`src/feature/` — LSP Feature Implementations&quot;">​</a></h3><p>Concrete implementations of LSP features. Each feature decides what the user sees — which items, their text, their edits and their protocol form — from the inputs it is given: a <code>CompilationUnit</code>, the index (<code>IndexQuery</code>), a document&#39;s text. This layer is purely computational -- it has no involvement with network communication, state management, or process scheduling.</p><p>Includes: code completion, hover information, signature help, semantic highlighting, inlay hints, document symbols, document links, folding ranges, formatting, diagnostics, etc.</p><blockquote><p><code>feature/</code> decides each answer; the server routes each request to the source that can answer it now, gathers the feature&#39;s inputs, calls it and replies. Cross-file navigation features (go to definition, find references, etc.) answer from the index (<code>IndexQuery</code>). Some features involve multi-phase processing -- for example, include path completion in code completion can be resolved at the syntax layer without full compilation.</p></blockquote><h3 id="src-worker-—-worker-processes" tabindex="-1"><code>src/worker/</code> — Worker Processes <a class="header-anchor" href="#src-worker-—-worker-processes" aria-label="Permalink to &quot;`src/worker/` — Worker Processes&quot;">​</a></h3><ul><li><code>WorkerPool</code>: Manages worker process lifecycles and scheduling — spawn/monitor/respawn with crash budgets and cooldown revival, attribution of every worker death to the request that caused it, a deadline on every request, stateful placement with document affinity, and stateless dispatch with priority queues and foreground-aware capacity</li><li><code>StatefulWorker</code>: Holds document ASTs and serves query requests</li><li>Stateless workers execute one-shot tasks (PCH/PCM builds, completion, formatting, indexing runs)</li></ul><h3 id="src-project-—-projects-and-what-they-build" tabindex="-1"><code>src/project/</code> — Projects and What They Build <a class="header-anchor" href="#src-project-—-projects-and-what-they-build" aria-label="Permalink to &quot;`src/project/` — Projects and What They Build&quot;">​</a></h3><p>A project is what one set of compilation databases and one cache directory describe: the state derived from files on disk, independent of editors, and the builds it runs over that state — its PCHs, its modules and its index. The command line runs one project. The server runs one per workspace folder, plus one for any file opened outside them whose directory or an ancestor holds a <code>clice.toml</code> or a <code>compile_commands.json</code>, and routes each file to the project that compiles it. A subdirectory with a configuration of its own is its own project: the one above it loads no database there and takes none of its files as its own, unless a database of its own lists them.</p><ul><li><code>Project</code>: The disk-truth aggregate — configuration, its rules (<code>Rules</code>), compilation database, members, dependency graph, the PCH and PCM entries, persisted index and the queries over it (<code>IndexQuery</code>, with its freshness gate), and the task graph its builds run on, with the event loop and worker pool its owner hands it. One class whose operations are its members, split across files by subject (<code>command/</code>, <code>graph/</code>, <code>background/</code>). Core invariant: unsaved buffer contents of open files never modify what a <code>Project</code> says of the disk; the one thing it learns from a buffer, whether a header compiles alone, is recorded under that text&#39;s version, which a reader of the disk ignores until the disk holds it</li><li>Opening (<code>Project::open</code>), one way for every entry point, in a fixed order: the rules under the configuration, the cache store and index database, the databases and provisional members the index remembers, the build and its dependency graph, then the saved index reconciled with the build</li><li>Discovery: where a project&#39;s compilation databases are and how they are watched — a rewrite reloaded once it holds for two looks, a discovered database&#39;s presence ranking it, the places one may appear at watched until it does —, which directory a file&#39;s project is rooted at, and which subdirectories are projects of their own</li><li>Members: what the build compiles — each file&#39;s database entries under the rules, the sources a rule&#39;s default command covers, and the provisional members (a source the user opened or saved that no database lists) — and the commands they compile under</li><li>Changes: what a change of the project&#39;s inputs invalidates, a file on disk or the build&#39;s commands — the include and module graphs rescanned, the PCMs and the units that read the file gone stale, the closed units booked to reindex, a vanished file forgotten. The project never calls its owner: the server hands it its open documents and what their compiles read, and hears back which of them went stale</li><li>Command resolution: the compile command a file compiles under, from the project alone: selected from six tiers in order — the host the user chose, the file&#39;s own command, the host ranking first, a rule&#39;s default command, the command of a nearby unit it borrows, clice&#39;s own fallback — each a candidate naming the file it is the command of, then rendered with the includer context a header needs; and the identity of a unit&#39;s command — the command it compiles under, rules applied, the project root written as <code>${workspace}</code> so a moved checkout keeps it — which its index, include trees, self-containment checks and header contexts are keyed by</li><li><code>Hosting</code>: What clice knows of the headers that compile in a unit&#39;s context, which the editor and <code>clice inspect</code> read alike: the hosts&#39; include trees, whether each header compiles alone (saved with the PCH and PCM records), the includer contexts synthesized, and what a file outside the build can borrow</li><li>Contexts: the contexts a file can compile in — its own commands and the hosts whose commands it can compile under — whether a user&#39;s choice still holds, and the format the choices are saved in</li><li><code>TaskGraph</code>: The shared build graph. Every expensive product is a node — a preamble PCH, a module&#39;s PCM, an open document&#39;s AST, one unit&#39;s compile for its index or its lint; whoever waits on a node carries how to build it, concurrent requests for the same node join one attempt instead of duplicating work, a clean node&#39;s product is checked when a waiter reaches it, cancellation is cooperative, and edges drive dependency-aware invalidation</li><li>PCHs and modules: building preamble PCHs (keyed by content) and C++20 module PCMs (with import edges and provider tracking), each entry holding its product and its last build&#39;s failure, and what the two share (<code>Precompiled</code>): a build&#39;s key and blob, the check of a cached build against the inputs it recorded, refusing a build that failed or crashed a worker until the files it is known to have read change (and a PCH its readers keep failing to read, for a while), and sending one to a stateless worker</li><li>Units: one translation unit compiled on a stateless worker for its index or its lint, shared by the background index and <code>clice lint</code></li><li><code>BackgroundIndex</code>: started by the project&#39;s owner — the server when it indexes, <code>clice index</code> at once, <code>clice lint --index</code> after its own pass — it runs passes over its queue of owed reindexes (<code>ReindexQueue</code>, which holds each unit&#39;s reason), admits only the build&#39;s units, feeds them through stateless workers, taking only the capacity the foreground leaves, and merges what comes back; a unit an open document&#39;s compile indexes is left to that document until it closes, and a run&#39;s skipped-body diagnostics are kept with the file&#39;s last attempt; the end of an attempt and the index&#39;s changes are signals its owner subscribes to</li><li><code>SavedMembers</code>: Which databases listed each file when the index was last saved, and the provisional members. Loading reindexes a unit whose command changed while no server ran, since its index records the command it was built with, and drops the index of one no database lists any more — when every database that listed it loaded, so one that failed to load keeps serving</li><li>Saving and loading: one transaction writes the index&#39;s changes with what the database carries beside it — the members, the PCH and PCM records, the editor&#39;s context choices — and the load reads them back; shutting down (<code>Project::shutdown</code>) stops the background index, winds down the graph&#39;s attempts, saves a last time and closes the cache store</li><li><code>Memo</code>: Results remembered by request with the trace of the files each read, checked on lookup: the hosts&#39; include trees, the self-containment checks and the header contexts synthesized</li></ul><h3 id="src-server-—-server-runtime" tabindex="-1"><code>src/server/</code> — Server Runtime <a class="header-anchor" href="#src-server-—-server-runtime" aria-label="Permalink to &quot;`src/server/` — Server Runtime&quot;">​</a></h3><p>The language server&#39;s core runtime, assembling all the layers above into a running service: one class per boundary of the design, each larger one in a directory of its own with its work split in files.</p><ul><li><code>MasterServer</code> (<code>master/</code>): The process. Owns the file table, the worker pool and the projects served, and holds the editor&#39;s state, one per process: the open documents — each with the project it belongs to, and the documents open under a second name of its file — and the user&#39;s context choices. It routes each open file to the project that compiles it, and moves a document to another project by changing its owner; the lifecycle, the polling and shutdown are its</li><li><code>Session</code>: One open document — its text, version and generation — and what crashed on it: a kind of work that crashed a worker on the document pauses until the document changes (spaced and bounded) or is saved. The records live as long as the document is open</li><li><code>LSPClient</code> (<code>client/</code>): The connection to the editor: the handshake and the client&#39;s capabilities, the document notifications handed to <code>MasterServer</code>, every language request — each written once, in its handler, behind one check of the server&#39;s lifecycle — clice&#39;s own requests, pushing diagnostics and the one refresh, progress, and the test hooks</li><li><code>ServedProject</code> (<code>served_project/</code>): One served project: its project, the open documents routed to it and what it derives for them — compiling them; what answers a request on them now (the worker&#39;s AST, the PCH&#39;s cached preamble products, or the index, by readiness: an up-to-date AST when there is one, otherwise results computed from the index at once) and asking the workers, each dispatch admitted by the document&#39;s crash records and answering <code>ContentModified</code> for a buffer the client already edited away; what the project&#39;s changes mean for the open documents; the open documents&#39; commands under their context choices; and the open documents as the reads of the index take them. Under <code>readonly = on/auto</code>, documents serve from the index until an edit escalates them to full AST service; compilation is pull-based throughout, triggered by requests rather than lifecycle events</li><li>Protocols: the LSP extension types, and the control channel through which <code>clice index</code> and <code>clice query --fresh</code> ask a running server to index — a loopback listener the server opens while it holds the project&#39;s index writer lock, recorded next to the lock for the command-line tools to find</li></ul><p>See <a href="./multi-process">Multi-process Architecture</a>.</p><h3 id="src-driver-—-subcommands" tabindex="-1"><code>src/driver/</code> — Subcommands <a class="header-anchor" href="#src-driver-—-subcommands" aria-label="Permalink to &quot;`src/driver/` — Subcommands&quot;">​</a></h3><p>Entry points for the <code>clice</code> binary: <code>serve</code> (the LSP server), <code>worker</code>, <code>index</code> (batch indexing), <code>lint</code> (batch clang-tidy), <code>inspect</code>, <code>format</code>, <code>query</code>, <code>refactor</code>, and <code>analyze</code>. <code>index</code> and <code>lint</code> run a project of their own with a worker pool of their own, headless.</p><h2 id="inter-module-relationships" tabindex="-1">Inter-module Relationships <a class="header-anchor" href="#inter-module-relationships" aria-label="Permalink to &quot;Inter-module Relationships&quot;">​</a></h2><p>The data flow roughly follows this direction:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>command (structured compile commands)</span></span>\n<span class="line"><span>    ↓</span></span>\n<span class="line"><span>project (task graph: PCH / PCM / AST / unit nodes) ──→ worker (processes)</span></span>\n<span class="line"><span>    ↓ products</span></span>\n<span class="line"><span>compile (drives Clang compilation)</span></span>\n<span class="line"><span>    ↓</span></span>\n<span class="line"><span>semantic (semantic map) ──→ index (TUIndex / shards / ProjectIndex)</span></span>\n<span class="line"><span>    ↓</span></span>\n<span class="line"><span>feature (produces LSP responses)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>The server layer assembles all of the above via sessions, routing,</span></span>\n<span class="line"><span>invalidation, and transports into a runnable service.</span></span></code></pre></div><p><code>support</code>, <code>vfs</code>, <code>config</code>, and <code>syntax</code> are cross-cutting layers shared by multiple modules.</p>',50)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
